window.AZ_BANK = window.AZ_BANK || [];
window.AZ_PBQ = window.AZ_PBQ || [];
window.AZ_BANK.push(
  {"id":"d1-001","domain":1,"objective":"1.1","type":"single","question":"What is cloud computing?","options":["The delivery of computing services over the internet","A datacenter that an organization builds and operates for its own use","Software that is installed and run on each user's computer","A private network that connects an organization's branch offices"],"answer":[0],"explanation":"Cloud computing is the delivery of computing services such as compute, storage, and networking over the internet, typically billed by use. A self-built datacenter and locally installed software are the traditional alternatives, and a branch network is just connectivity.","difficulty":1,"tags":["cloud computing","definition"]},
  {"id":"d1-002","domain":1,"objective":"1.1","type":"single","question":"In the shared responsibility model, which responsibility always remains with the customer, regardless of the cloud service type?","options":["Physical hosts","Operating system","Information and data","Physical network"],"answer":[2],"explanation":"The customer is always responsible for its information and data, along with devices and accounts and identities. Physical hosts and the physical network always belong to the provider, and operating system responsibility depends on the service type.","difficulty":1,"tags":["shared responsibility","data"]},
  {"id":"d1-003","domain":1,"objective":"1.1","type":"single","question":"A logistics company moves a line-of-business application from its own servers to Azure virtual machines. Who is responsible for applying security updates to the operating system on the virtual machines?","options":["Microsoft","The logistics company","The application vendor","Microsoft and the logistics company share the task equally"],"answer":[1],"explanation":"Virtual machines are IaaS, where the customer manages the operating system, including patching. Microsoft manages the operating system only in PaaS and SaaS, and the split is not an equal share for this layer.","difficulty":2,"tags":["shared responsibility","IaaS","patching"]},
  {"id":"d1-006","domain":1,"objective":"1.1","type":"multi","question":"Which responsibilities are always retained by the customer in the shared responsibility model? Choose THREE.","options":["Information and data","Physical datacenter","Devices that connect to the cloud","Physical network","Accounts and identities","Physical hosts"],"answer":[0,2,4],"explanation":"Information and data, devices, and accounts and identities are the customer's responsibility in IaaS, PaaS, and SaaS alike. The physical datacenter, network, and hosts are always the provider's responsibility in the cloud.","difficulty":2,"tags":["shared responsibility","customer"]},
  {"id":"d2-001","domain":2,"objective":"2.1","type":"single","question":"What is an Azure region?","options":["A single datacenter that is assigned to one customer","A geographical area that contains one or more datacenters connected by a low-latency network","A logical container that holds related Azure resources","A group of subscriptions that share the same policies"],"answer":[1],"explanation":"A region is a geographical area with at least one, and potentially several, nearby datacenters networked together with low latency. A logical container for resources is a resource group, and a group of subscriptions is a management group.","difficulty":1,"tags":["regions"]},
  {"id":"d2-002","domain":2,"objective":"2.1","type":"single","question":"A retailer runs an application in the East US region. The company wants a second copy of the application in a location that Azure will not update at the same time as East US and that is far enough away to survive a regional disaster. What should the company use?","options":["A second availability zone in East US","An availability set","The region paired with East US","A second resource group in East US"],"answer":[2],"explanation":"Paired regions are at least 300 miles apart and receive planned updates one region at a time, so the paired region fits both requirements. Availability zones and availability sets stay inside East US, and a resource group is only a logical container.","difficulty":2,"tags":["region pairs","disaster recovery"]},
  {"id":"d2-004","domain":2,"objective":"2.1","type":"single","question":"A United States federal agency must deploy workloads to an instance of Azure that is physically and logically isolated from the public Azure regions and operated by screened US persons. What should the agency use?","options":["Azure Government","Azure operated by 21Vianet","A region pair in the US geography","A dedicated management group"],"answer":[0],"explanation":"Azure Government is the sovereign cloud for US government agencies and their partners, isolated and run by screened US persons. The 21Vianet regions serve China, a region pair is still public Azure, and a management group only organizes subscriptions.","difficulty":1,"tags":["sovereign regions","Azure Government"]},
  {"id":"d2-003","domain":2,"objective":"2.1","type":"multi","question":"Which two statements describe Azure region pairs? Choose TWO.","options":["Planned Azure updates are rolled out to one region of a pair at a time","The two regions of a pair are always located in the same city","If a widespread outage occurs, one region of each pair is prioritized for recovery","Every Azure service replicates its data to the paired region automatically","A region pair is made up of three or more availability zones"],"answer":[0,2],"explanation":"Region pairs get sequential planned updates and prioritized recovery of one region per pair. The regions are at least 300 miles apart, only some services replicate to the pair automatically, and availability zones are a separate concept inside one region.","difficulty":2,"tags":["region pairs"]},
  {"id":"d3-001","domain":3,"objective":"3.1","type":"single","question":"A company plans to deploy several virtual machines. Which factor affects the monthly cost of the virtual machines?","options":["The resource group that contains the virtual machines","The number of tags applied to the virtual machines","The Azure region where the virtual machines are deployed","The management group above the subscription"],"answer":[2],"explanation":"Prices differ between regions because power, labor, taxes, and fees vary by location. Resource groups, tags, and management groups are free organizational constructs and do not change the price of a resource.","difficulty":1,"tags":["cost factors","geography"]},
  {"id":"d3-002","domain":3,"objective":"3.1","type":"single","question":"A startup deleted ten test virtual machines last month, but the invoice still shows charges for the managed disks and public IP addresses that were attached to them. Which cost factor does this describe?","options":["Maintenance","Geography","Subscription type","Azure Marketplace"],"answer":[0],"explanation":"Maintenance is about keeping the environment clean: resources provisioned alongside a VM can be left behind when the VM is removed and keep generating charges. Geography concerns regional price differences, and the other two factors concern allowances and third-party offers.","difficulty":2,"tags":["cost factors","maintenance","orphaned resources"]},
  {"id":"d3-003","domain":3,"objective":"3.1","type":"single","question":"Which term completes the sentence: Data transfer out of Azure datacenters is priced according to ______, which are geographical groupings of Azure regions.","options":["availability zones","region pairs","management groups","billing zones"],"answer":[3],"explanation":"A billing zone is a geographical grouping of regions used only for data-transfer pricing. Availability zones and region pairs are resiliency constructs, and management groups organize subscriptions.","difficulty":1,"tags":["billing zones","network traffic"]},
  {"id":"d3-018","domain":3,"objective":"3.1","type":"multi","question":"Which alert types appear under cost alerts in Microsoft Cost Management? Choose THREE.","options":["Budget alerts","Resource health alerts","Credit alerts","Metric alerts","Department spending quota alerts"],"answer":[0,2,4],"explanation":"Cost alerts consist of budget alerts, credit alerts, and department spending quota alerts. Resource health alerts belong to Azure Service Health, and metric alerts belong to Azure Monitor.","difficulty":1,"tags":["cost alerts","Cost Management"]}
);
window.AZ_PBQ.push(
  {"id":"pbq-002","domain":1,"objective":"1.1","type":"match","title":"Cloud computing statements","instructions":"For each statement, select Yes if the statement is true. Otherwise, select No.","left":["In a consumption-based model, you pay only for the resources that you use.","A hybrid cloud requires an organization to move all of its workloads out of its on-premises datacenter.","A public cloud lets an organization deploy resources without purchasing hardware up front."],"right":["Yes","No"],"answer":[0,1,0],"explanation":"Statement 1 is Yes: consumption-based pricing bills for what is used and nothing more. Statement 2 is No: a hybrid cloud combines on-premises (private) resources with public cloud resources, so workloads can stay on-premises. Statement 3 is Yes: public cloud resources are rented from the provider, so there is no capital expenditure on hardware."},
  {"id":"pbq-005","domain":1,"objective":"1.3","type":"order","title":"Order by customer responsibility","instructions":"Arrange the options from the one in which the customer manages the most (top) to the one in which the customer manages the least (bottom).","items":["PaaS","On-premises datacenter","SaaS","IaaS"],"answer":[1,3,0,2],"explanation":"On-premises, the customer manages everything, including the building and hardware. With IaaS the provider takes over the physical layer and the customer manages the operating system and above. With PaaS the customer manages only applications and data. With SaaS the customer manages only its data, users, and settings."},
  {"id":"pbq-001","domain":1,"objective":"1.1","type":"config","title":"Shared responsibility by service type","instructions":"For each area of responsibility, select who is responsible under each cloud service type.","columns":[{"key":"iaas","label":"IaaS","choices":["Customer","Microsoft","Shared"]},{"key":"paas","label":"PaaS","choices":["Customer","Microsoft","Shared"]},{"key":"saas","label":"SaaS","choices":["Customer","Microsoft","Shared"]}],"rows":[{"label":"Operating system","fixed":{},"answer":{"iaas":"Customer","paas":"Microsoft","saas":"Microsoft"}},{"label":"Physical datacenter","fixed":{},"answer":{"iaas":"Microsoft","paas":"Microsoft","saas":"Microsoft"}},{"label":"Information and data","fixed":{},"answer":{"iaas":"Customer","paas":"Customer","saas":"Customer"}},{"label":"Network controls","fixed":{},"answer":{"iaas":"Customer","paas":"Shared","saas":"Microsoft"}}],"explanation":"Operating system: the customer installs and patches it on IaaS virtual machines, while Microsoft manages it for PaaS and SaaS. Physical datacenter: always Microsoft in the cloud. Information and data: always the customer, whatever the service type. Network controls: the customer's job in IaaS, shared in PaaS, and Microsoft's in SaaS."},
  {"id":"pbq-007","domain":2,"objective":"2.2","type":"match","title":"Match the compute service","instructions":"Match each requirement to the Azure compute service that meets it. Each service can be used once, and two services are not used.","left":["Run a short piece of code whenever a message arrives, with no infrastructure to manage and no charge while idle.","Run a group of identical, load-balanced virtual machines whose number increases and decreases automatically with demand.","Run a server on which administrators need full control of the operating system to install custom software.","Give employees a Windows desktop and their applications, hosted in Azure and reachable from any device.","Run a single container quickly without managing virtual machines or a container orchestrator."],"right":["Azure Functions","Virtual Machine Scale Sets","Azure Virtual Machines","Azure Virtual Desktop","Azure Container Instances","Availability set","Azure DNS"],"answer":[0,1,2,3,4],"unique":true,"explanation":"Azure Functions runs event-driven code serverlessly. Virtual Machine Scale Sets create and automatically scale identical VMs. Azure Virtual Machines give full operating system control. Azure Virtual Desktop delivers desktops and apps from Azure. Azure Container Instances runs a container without VM or orchestrator management. An availability set only spreads VMs across fault and update domains, and Azure DNS is a networking service."},
  {"id":"pbq-006","domain":2,"objective":"2.1","type":"order","title":"Azure management hierarchy","instructions":"Arrange the levels of the Azure management hierarchy from the top level (broadest scope) to the bottom level (narrowest scope).","items":["Resource group","Root management group","Resource","Subscription","Child management group"],"answer":[1,4,3,0,2],"explanation":"The root management group sits at the top of each directory. Other management groups nest beneath it and contain subscriptions. Each subscription contains resource groups, and each resource group contains resources. Policies and role assignments made at one level are inherited by every level below it."},
  {"id":"pbq-008","domain":2,"objective":"2.2","type":"config","title":"Choose the connectivity option","instructions":"For each requirement, select the Azure networking feature to use and whether the traffic travels over the public internet.","columns":[{"key":"service","label":"Feature","choices":["Azure VPN Gateway","Azure ExpressRoute","Virtual network peering","Azure DNS"]},{"key":"internet","label":"Uses the public internet","choices":["Yes","No"]}],"rows":[{"label":"Connect a branch office network to an Azure virtual network through an encrypted tunnel over the office's existing internet connection","fixed":{},"answer":{"service":"Azure VPN Gateway","internet":"Yes"}},{"label":"Connect a datacenter to Azure over a dedicated private connection supplied by a connectivity provider","fixed":{},"answer":{"service":"Azure ExpressRoute","internet":"No"}},{"label":"Let resources in two Azure virtual networks in different regions communicate with each other directly, without deploying a gateway","fixed":{},"answer":{"service":"Virtual network peering","internet":"No"}},{"label":"Let one remote employee's laptop connect securely to an Azure virtual network from home","fixed":{},"answer":{"service":"Azure VPN Gateway","internet":"Yes"}}],"explanation":"A site-to-site VPN through Azure VPN Gateway sends encrypted traffic over the internet. ExpressRoute is a private circuit through a connectivity provider and does not use the public internet. Peering links virtual networks, and the traffic stays on the Microsoft backbone network. A point-to-site VPN, also through VPN Gateway, connects a single client over the internet. Azure DNS hosts DNS domains and does not connect networks."},
  {"id":"pbq-013","domain":3,"objective":"3.1","type":"match","title":"Cost management statements","instructions":"For each statement, select Yes if the statement is true. Otherwise, select No.","left":["The pricing calculator shows the actual charges from your most recent Azure invoice.","When spending reaches a budget amount in Microsoft Cost Management, Azure automatically deletes the resources that caused the spending.","Tags can be used to group and filter costs by department in cost analysis."],"right":["Yes","No"],"answer":[1,1,0],"explanation":"Statement 1 is No: the pricing calculator estimates the cost of resources you plan to deploy; actual charges are in Microsoft Cost Management. Statement 2 is No: a budget triggers alerts when a threshold is reached and does not delete resources. Statement 3 is Yes: tags such as Department are metadata that cost analysis can group and filter by."},
  {"id":"pbq-018","domain":3,"objective":"3.4","type":"order","title":"Health information by scope","instructions":"Arrange the three Azure Service Health components from the broadest scope (top) to the narrowest scope (bottom).","items":["Resource Health","Azure Status","Service Health"],"answer":[1,2,0],"explanation":"Azure Status shows the state of all Azure services in every region. Service Health narrows that to the services and regions you actually use. Resource Health reports on your individual resources, such as one virtual machine."},
  {"id":"pbq-014","domain":3,"objective":"3.2","type":"config","title":"Choose the governance tool and scope","instructions":"For each requirement, select the governance tool to use and the single scope at which to apply it with the least administrative effort.","columns":[{"key":"tool","label":"Tool","choices":["Azure Policy","Resource lock","Microsoft Purview"]},{"key":"scope","label":"Scope","choices":["Management group","Subscription","Resource group","Resource"]}],"rows":[{"label":"Allow resources to be created only in two approved regions across all 12 of the company's subscriptions","fixed":{},"answer":{"tool":"Azure Policy","scope":"Management group"}},{"label":"Prevent anyone from accidentally deleting one production storage account, without affecting other resources in its resource group","fixed":{},"answer":{"tool":"Resource lock","scope":"Resource"}},{"label":"Require a CostCenter tag on everything created in the Finance resource group, and nowhere else","fixed":{},"answer":{"tool":"Azure Policy","scope":"Resource group"}},{"label":"Make every resource in one subscription unchangeable during an audit freeze","fixed":{},"answer":{"tool":"Resource lock","scope":"Subscription"}}],"explanation":"Row 1: Azure Policy enforces rules such as allowed locations, and one assignment at a management group is inherited by all subscriptions beneath it. Row 2: a Delete lock on the single resource blocks deletion of that resource only. Row 3: a policy that requires a tag, assigned to the resource group, affects only that group. Row 4: a ReadOnly lock on the subscription is inherited by every resource group and resource in it. Microsoft Purview governs and classifies data; it does not restrict Azure resource deployment."}
);
